using System.IO;
using System.Diagnostics;
using System.Text.Json;
using System.Windows.Controls;
using PhotoTrail.Windows;
static partial class Program {
 static string R08bRule(long start=1,bool directory=false,int counter=0)=>JsonSerializer.Serialize(new RenameRule("action"){Action="number-set",Start=start,PerDirectory=directory,Counter=counter,Prefix="seq_"});
 static async Task R08bChecks(){
  await ImportDone();var originals=R06Rows();var seed=originals.Single(r=>Path.GetFileName(Doc(r).FilePath)=="embedded.jpg");var root=Path.Combine(folder,"sequences");Directory.CreateDirectory(root);for(int i=0;i<100;i++)File.Copy(Doc(seed).FilePath,Path.Combine(root,$"input-{i:D3}.jpg"));await ImportMore(root);var rows=R06Rows().Where(r=>Path.GetFileName(Doc(r).FilePath).StartsWith("input-")).ToArray();Check(rows.Length==100,"R08b-import100");SelectMetadataTab("重命名");
  Control<ComboBox>("RenameProcessingSort").SelectedIndex=0;Control<ComboBox>("RenameConflictChoice").SelectedIndex=0;var times=new List<object>();
  foreach(var count in new[]{1,20,100}){RefreshCompareSelection(rows.Take(count).ToArray());Control<TextBox>("RenameRules").Text=R08bRule(counter:1);var watch=Stopwatch.StartNew();await R08Preview();var previewMs=watch.Elapsed.TotalMilliseconds;var shown=Control<DataGrid>("RenamePreview").Items.Cast<RenameFile>().ToArray();Check(shown.Length==count&&shown[0].NewName=="seq_001.jpg"&&shown[^1].NewName==$"seq_{count:D3}.jpg","R08b-entire-frozen-sequence-"+count);watch.Restart();Action("FreezeRename");await RenameWait();var freezeMs=watch.Elapsed.TotalMilliseconds;Check(Field("frozenRenamePlan")is RenamePlan p&&p.Files.Count==count,"R08b-full-freeze-"+count);Control<TextBox>("RenameRules").Text=R08bRule(100);Check(Field("frozenRenamePlan")is null&&!File.Exists(Environment.GetEnvironmentVariable("PHOTOTRAIL_RENAME_COUNTERS")),"R08b-preview-cancel-does-not-advance-"+count);times.Add(new{count,previewMs,freezeMs});}
  var other=Path.Combine(folder,"other");Directory.CreateDirectory(other);File.Copy(Doc(seed).FilePath,Path.Combine(other,"other.jpg"));await ImportMore(other);var separate=R06Rows().Single(r=>Doc(r).FilePath==Path.Combine(other,"other.jpg"));RefreshCompareSelection([rows[0],rows[1],separate]);Control<TextBox>("RenameRules").Text=R08bRule(directory:true);await R08Preview();var directoryNames=Control<DataGrid>("RenamePreview").Items.Cast<RenameFile>().ToArray();Check(directoryNames.Count(f=>f.NewName=="seq_001.jpg")==2&&directoryNames.Count(f=>f.NewName=="seq_002.jpg")==1,"R08b-per-real-directory");
  var selected=originals.Where(r=>Path.GetFileName(Doc(r).FilePath)is "embedded.jpg" or "paired.jpg" or "raw.DNG").ToArray();RefreshCompareSelection(selected);Control<TextBox>("RenameRules").Text=R08bRule(counter:1);Control<TextBox>("RenameSchemeName").Text="R08b持续编号";Action("SaveAsRenameScheme");await R08Preview();var library=RenameSchemeLibrary.Open(RenameSchemeLibrary.DefaultPath);Check(library.State.Schemes.Single(s=>s.Id==library.State.LastId).Name=="R08b持续编号","R08b-create-persist-scheme");
  Action("FreezeRename");await RenameWait();Action("ExecuteRename");await RenameWait();Check(Control<TextBlock>("RenameStatus").Text.Contains("更名及内容核验完成"),"R08b-real-five-member-execution");var journal=Control<TextBox>("RenameJournalPath").Text;var result=RenameExecutor.ReadJournal(journal);Check(result.Complete&&result.Files.Count==5,"R08b-full-paired-result");foreach(var file in result.Files)Check(await PhotoDocument.HashAsync(file.Current)==file.Hash,"R08b-content-after-move");var counters=JsonDocument.Parse(File.ReadAllBytes(Environment.GetEnvironmentVariable("PHOTOTRAIL_RENAME_COUNTERS")!));Check(counters.RootElement.GetProperty("values").GetProperty("1").GetInt64()==4,"R08b-three-groups-counter-committed");
  Action("RestoreRename");await RenameWait();Check(Control<TextBlock>("RenameStatus").Text.Contains("恢复完成"),"R08b-explicit-restore");foreach(var file in result.Files)Check(await PhotoDocument.HashAsync(file.Source)==file.Hash,"R08b-restored-content");Check(JsonDocument.Parse(File.ReadAllBytes(Environment.GetEnvironmentVariable("PHOTOTRAIL_RENAME_COUNTERS")!)).RootElement.GetProperty("values").GetProperty("1").GetInt64()==4,"R08b-restore-no-counter-reuse");
  File.WriteAllText(Path.Combine(folder,"r08b-ui-results.json"),JsonSerializer.Serialize(new{passed=evidence.Count,evidence,performance=times},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("R08B_WPF_CHECKS="+evidence.Count);window.Close();
 }
}
